import { formatUrlWithWorkspaceId } from '../../../../../core/public/utils';
export const navigateToWorkspacePageWithUseCase = (application, useCaseTitle, appId) => {
  const newUrl = application.getUrlForApp(appId, {
    absolute: true
  });
  if (newUrl) {
    const url = new URL(newUrl);
    url.hash = `/?useCase=${useCaseTitle}`;
    application.navigateToUrl(url.toString());
  }
};
export const navigateToAppWithinWorkspace = ({
  application,
  http
}, workspaceId, appId, hash) => {
  const newUrl = formatUrlWithWorkspaceId(application.getUrlForApp(appId, {
    absolute: true
  }), workspaceId, http.basePath);
  if (newUrl) {
    const url = new URL(newUrl);
    if (hash) {
      url.hash = hash;
    }
    application.navigateToUrl(url.toString());
  }
};